public static GUPPriceTreeName METFindPriceTreeNameByPurchId(PurchId _purchId)
{
    GUPPriceTreeName priceTreeName;

    // Find price tree name when price tree is enabled.
    GUPPricingTree matchedPriceTree = GUPPricingTree::METGetPriceTreeByPurchId(_purchId);

    if (matchedPriceTree.RecId && !GUPPricingTree::shouldSkipFindPriceTree())
    {
        priceTreeName = matchedPriceTree.Name;
    }

    return priceTreeName;
}

public static GUPPricingTree METGetPriceTreeByPurchId(PurchId _purchId, boolean _showError = true)
{
    GUPPricingTree matchedPriceTree;
    GUPParameters gupParameters = GUPParameters::find();

    if (gupParameters.EnablePriceTree)
    {
        EcoResValue ecoResValueOnPurchOrder = GUPPricingTree::MetGetEcoResValueFromPurchId(_purchId, false);

        matchedPriceTree = GUPPricingTree::METGetPriceTreeForPurchOrder(ecoResValueOnPurchOrder, _showError);
    }
    else if (!gupParameters.EnablePriceTree)
    {
        matchedPriceTree = GUPPricingTree::METFindSinglePriceTree();
        if (!matchedPriceTree.RecId || matchedPriceTree.Status != GUPDisabledEnabled::Enabled)
        {
            throw error("@GlobalUnifiedPricing:CheckSinglePriceTreeSetup");
        }
    }

    return matchedPriceTree;
}

static EcoResValue MetGetEcoResValueFromPurchId(PurchId _purchId, boolean _showWarning = true)
{
    GUPSalesTableInstanceValue salesTableInstanceValue = GUPSalesTableInstanceValue::findBySalesTable(_purchId, curExt());
    str warningMessage = strFmt("@GlobalUnifiedPricing:SalesOrderMissingAttribute", _purchId);
    return GUPPricingTree::METGetEcoResValueFromInstanceValue(salesTableInstanceValue.RecId, warningMessage, _showWarning);
}

public static Set METGetComponentCodeNamesLinkedWithPriceTreeFromPurchId(PurchId _purchId)
{
    Set componentCodeNames = new Set(Types::String);

    GUPPricingTree matchedPriceTree = GUPPricingTree::METGetPriceTreeByPurchId(_purchId, false);

    if (matchedPriceTree.RecId)
    {
        GUPPriceComponentCodeSetup setup;
        while select PriceComponentCodeName from setup where setup.PricingTreeName == matchedPriceTree.Name
        {
            componentCodeNames.add(setup.PriceComponentCodeName);
        }
    }

    return componentCodeNames;
}

static GUPPricingTree METFindSinglePriceTree()
{
    GUPPricingTree gupPricingTree;

    select firstonly gupPricingTree
        where gupPricingTree.IsSingleTree == NoYes::Yes;
    return gupPricingTree;
}

static GUPPricingTree METGetPriceTreeForPurchOrder(EcoResValue _ecoResValueOnPurchOrder, boolean _showError = true)
{
    GUPPricingTree matchedPriceTree = GUPPricingTree::METGetPriceTreeByEcoResValue(_ecoResValueOnPurchOrder);

    if (!matchedPriceTree.RecId && _showError)
    {
        error("@GlobalUnifiedPricing:CheckPriceTreeSetup");
    }

    return matchedPriceTree;
}

static EcoResValue METGetEcoResValueFromInstanceValue(RefRecId _recId, str _warningMessage, boolean _showWarning = true)
{
    EcoResValue ecoResValue;
    EcoResAttributeValue ecoResAttributeValue = GUPPricingTree::METGetPriceTreeAttributeValue(_recId);
    if (ecoResAttributeValue.RecId)
    {
        ecoResValue = EcoResValue::find(ecoResAttributeValue.Value);
    }
    else
    {
        if (_showWarning)
        {
            warning(_warningMessage);
        }
    }

    return EcoResValue::getConcreteEcoResValueRecord(ecoResValue);
}

static EcoResAttributeValue METGetPriceTreeAttributeValue(RefRecId _instanceRecId)
{
    GUPParameters gupParameters;
    EcoResAttributeValue ecoResAttributeValue;

    select firstonly Value from ecoResAttributeValue
        where ecoResAttributeValue.InstanceValue == _instanceRecId
        exists join gupParameters
            where gupParameters.PriceTreeAttribute == ecoResAttributeValue.Attribute;

    return ecoResAttributeValue;
}

static GUPPricingTree METGetPriceTreeByEcoResValue(EcoResValue _ecoResValueOnSalesTable)
{
    GUPPricingTree gupPriceTree, matchedPriceTree;
    EcoResValue ecoResValueOnPriceTree;
    int cnt = 0;

    if (_ecoResValueOnSalesTable.RecId)
    {
        while select * from gupPriceTree
            where gupPriceTree.Status == GUPDisabledEnabled::Enabled
            && gupPriceTree.IsSingleTree == NoYes::No
        {
            ecoResValueOnPriceTree = gupPriceTree.METGetAttributeValueOnPriceTree();
            if (ecoResValueOnPriceTree.RecId && ecoResValueOnPriceTree.compareTo(_ecoResValueOnSalesTable) == 0)
            {
                matchedPriceTree = GUPPricingTree::find(gupPriceTree.Name);
                cnt++;

                if (cnt > 1)
                {
                    error("@GlobalUnifiedPricing:SalesOrderValidation_MultiPriceTree");
                    matchedPriceTree = null;

                    return matchedPriceTree;
                }
            }
        }

        if (cnt == 0)
        {
            error("@GlobalUnifiedPricing:SalesOrderValidation_NoPriceTree");
            matchedPriceTree = null;
        }
    }

    return matchedPriceTree;
}

private EcoResValue METGetAttributeValueOnPriceTree()
{
    EcoResValue ecoResValue;

    if (!GUPPricingTree::shouldSkipAttributeValueOnPriceTree())
    {
        GUPPriceTreeInstanceValue gupPriceTreeInstanceValue = GUPPriceTreeInstanceValue::findByPriceTree(this.Name, this.DataAreaId);
        EcoResAttributeValue ecoResAttributeValue = GUPPricingTree::METGetPriceTreeAttributeValue(gupPriceTreeInstanceValue.RecId);

        if (ecoResAttributeValue.RecId)
        {
            ecoResValue = EcoResValue::find(ecoResAttributeValue.Value);
        }
        else
        {
            warning(strFmt("@GlobalUnifiedPricing:GUPPriceTree_MissingAttributeValue", this.Name));
        }
    }

    return EcoResValue::getConcreteEcoResValueRecord(ecoResValue);
}
